          <!-- Wordmark -->
          <tr>
            <td align="center" style="padding: 40px 0 20px 0;">
              <p style="margin:0; color:#c9a555; font-size:24px; font-weight:700; letter-spacing:4px; text-transform:uppercase; font-family:'Rubik','Segoe UI',sans-serif;">
                PRIZMA OPTIC
              </p>
              <p style="margin:5px 0 0 0; color:#999999; font-size:12px; letter-spacing:2px; text-transform:uppercase; font-family:'Rubik','Segoe UI',sans-serif;">
                Luxury Eyewear Events
              </p>
            </td>
          </tr>

          <!-- Main Content -->
          <tr>
            <td class="mobile-padding" style="padding: 20px 50px 40px 50px; text-align:right;">

              <h1 style="margin:0 0 20px 0; font-size:26px; font-weight:700; color:#ffffff; line-height:1.3;">
                שלום %name%,
              </h1>

              <p style="margin:0 0 22px 0; font-size:16px; line-height:1.7; color:#cccccc;">
                מחר תיפתח ההרשמה ל-<strong style="color:#ffffff;">%event_name%</strong>.
              </p>

              <p style="margin:0 0 22px 0; font-size:15px; line-height:1.7; color:#bbbbbb;">
                אירוע ייעודי הנערך בזמנים מוגדרים בלבד, עם תנאים מיוחדים שנפתחים בעזרת קוד קופון אישי שיישלח לנרשמים מראש.
              </p>

              <!-- ═══ NOTICE CARD — canonical (canon §4.4 dark variant), Heroicons users ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color: rgba(201,165,85,0.06); border:1px solid rgba(201,165,85,0.40); border-radius:12px; margin-bottom:25px;">
                <tr>
                  <td style="padding: 16px 20px;">
                    <table border="0" cellpadding="0" cellspacing="0">
                      <tr>
                        <td valign="middle" style="padding-bottom:6px;">
                          <!-- Heroicons solid: users -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="#e8da94" style="vertical-align:middle; margin-left:6px;">
                            <path d="M4.5 6.375a4.125 4.125 0 118.25 0 4.125 4.125 0 01-8.25 0zM14.25 8.625a3.375 3.375 0 116.75 0 3.375 3.375 0 01-6.75 0zM1.5 19.125a7.125 7.125 0 0114.25 0v.003l-.001.119a.75.75 0 01-.363.63 13.067 13.067 0 01-6.761 1.873c-2.472 0-4.786-.684-6.76-1.873a.75.75 0 01-.364-.63l-.001-.122zM17.25 19.128l-.001.144a2.25 2.25 0 01-.233.96 10.088 10.088 0 005.06-1.01.75.75 0 00.42-.643 4.875 4.875 0 00-6.957-4.611 8.586 8.586 0 011.71 5.157v.003z"/>
                          </svg>
                          <span style="font-size:12px; font-weight:700; color:#e8da94; text-transform:uppercase; letter-spacing:0.15em;">מקומות מוגבלים</span>
                        </td>
                      </tr>
                    </table>
                    <p style="margin:0; font-size:14px; line-height:1.6; color:#cccccc;">
                      על מנת לשמור על רמת שירות וחוויית קנייה גבוהה, מספר המשתתפים באירוע הקרוב מוגבל ל-<strong style="color:#ffffff;">%event_max_attendees% משתתפים</strong>.
                    </p>
                  </td>
                </tr>
              </table>

              <p style="margin:0 0 28px 0; font-size:14px; line-height:1.6; color:#999999;">
                עם פתיחת ההרשמה תישלח הודעה נוספת עם קישור ייעודי לרישום. אין צורך לבצע שום פעולה בשלב זה.
              </p>

              <!-- ═══ CTA BUTTONS ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-top: 6px;">
                <tr>
                  <td align="center" style="padding: 6px 0 0 0;">
                    <p style="margin:0 0 14px 0; font-size:14px; color:#bbbbbb;">
                      בינתיים, להצצה במותגים ובמחירים:
                    </p>

                    <table border="0" cellpadding="0" cellspacing="0" role="presentation" style="margin: 0 auto;">
                      <tr>
                        <!-- Event Page -->
                        <td align="center" style="padding: 0 6px 10px 6px;">
                          <a href="https://prizma-optic.co.il/supersale/" class="mobile-btn" style="display:inline-block; padding:12px 22px; background-color:transparent; color:#c9a555; border: 1px solid #c9a555; font-family:'Rubik','Segoe UI',sans-serif; font-size:14px; font-weight:700; text-decoration:none; border-radius:9999px; letter-spacing:0.3px;">
                            <!-- Heroicons solid: sparkles -->
                            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="#c9a555" style="vertical-align:middle; margin-left:6px;">
                              <path fill-rule="evenodd" d="M9 4.5a.75.75 0 01.721.544l.813 2.846a3.75 3.75 0 002.576 2.576l2.846.813a.75.75 0 010 1.442l-2.846.813a3.75 3.75 0 00-2.576 2.576l-.813 2.846a.75.75 0 01-1.442 0l-.813-2.846a3.75 3.75 0 00-2.576-2.576l-2.846-.813a.75.75 0 010-1.442l2.846-.813A3.75 3.75 0 007.466 7.89l.813-2.846A.75.75 0 019 4.5zM18 1.5a.75.75 0 01.728.568l.258 1.036c.236.94.97 1.674 1.91 1.91l1.036.258a.75.75 0 010 1.456l-1.036.258c-.94.236-1.674.97-1.91 1.91l-.258 1.036a.75.75 0 01-1.456 0l-.258-1.036a2.625 2.625 0 00-1.91-1.91l-1.036-.258a.75.75 0 010-1.456l1.036-.258a2.625 2.625 0 001.91-1.91l.258-1.036A.75.75 0 0118 1.5zM16.5 15a.75.75 0 01.712.513l.394 1.183c.15.447.5.799.948.948l1.183.395a.75.75 0 010 1.422l-1.183.395c-.447.15-.799.5-.948.948l-.395 1.183a.75.75 0 01-1.422 0l-.395-1.183a1.5 1.5 0 00-.948-.948l-1.183-.395a.75.75 0 010-1.422l1.183-.395c.447-.15.799-.5.948-.948l.395-1.183A.75.75 0 0116.5 15z" clip-rule="evenodd"/>
                            </svg>
                            עמוד האירוע
                          </a>
                        </td>

                        <!-- Instagram -->
                        <td align="center" style="padding: 0 6px 10px 6px;">
                          <a href="https://www.instagram.com/optic_prizma" class="mobile-btn" style="display:inline-block; padding:12px 22px; background-color:transparent; color:#ffffff; border: 1px solid #2d2d2d; font-family:'Rubik','Segoe UI',sans-serif; font-size:14px; font-weight:700; text-decoration:none; border-radius:9999px; letter-spacing:0.3px;">
                            <!-- Heroicons outline: camera -->
                            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="1.5" style="vertical-align:middle; margin-left:6px;">
                              <path stroke-linecap="round" stroke-linejoin="round" d="M6.827 6.175A2.31 2.31 0 015.186 7.23c-.38.054-.757.112-1.134.175C2.999 7.58 2.25 8.507 2.25 9.574V18a2.25 2.25 0 002.25 2.25h15A2.25 2.25 0 0021.75 18V9.574c0-1.067-.75-1.994-1.802-2.169a47.865 47.865 0 00-1.134-.175 2.31 2.31 0 01-1.64-1.055l-.822-1.316a2.192 2.192 0 00-1.736-1.039 48.774 48.774 0 00-5.232 0 2.192 2.192 0 00-1.736 1.039l-.821 1.316z"/>
                              <path stroke-linecap="round" stroke-linejoin="round" d="M16.5 12.75a4.5 4.5 0 11-9 0 4.5 4.5 0 019 0zM18.75 10.5h.008v.008h-.008V10.5z"/>
                            </svg>
                            אינסטגרם
                          </a>
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>
              </table>

              <!-- Sign Off -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-top: 35px; border-top: 1px solid #2d2d2d;">
                <tr>
                  <td style="padding-top: 20px;">
                    <p style="margin:0; font-size:15px; color:#ffffff;">
                      בברכה,
                    </p>
                    <p style="margin:5px 0 0 0; font-size:15px; color:#c9a555; font-weight:700;">
                      צוות אופטיקה פריזמה
                    </p>
                  </td>
                </tr>
              </table>

            </td>
          </tr>

          <!-- Unsubscribe Block -->
          <tr>
            <td>
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-top: 0;">
                <tr>
                  <td align="center" style="padding: 18px 20px; color:#999999; font-size:12px; line-height:1.6;">
                    <p style="margin:0 0 6px 0;">
                      קיבלתם את המייל הזה כחלק מרשימת עדכוני אירועי המותגים של אופטיקה פריזמה.
                    </p>
                    <p style="margin:0 0 10px 0;">
                      אם אינכם מעוניינים לקבל מאיתנו עדכונים שוטפים והזמנות לאירועים עתידיים, ניתן להסיר בלחיצה:
                    </p>

                    <a href="%unsubscribe_url%" style="color:#c9a555; text-decoration:underline; font-weight:600;">
                      להסרה מרשימת התפוצה
                    </a>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

        </table>

        <!-- ═══ COPYRIGHT (under main card) ═══ -->
        <table border="0" cellpadding="0" cellspacing="0" width="600" class="container">
          <tr>
            <td align="center" style="padding: 20px 0; color:#666666; font-size:11px; line-height:1.6;">
              © כל הזכויות שמורות לאופטיקה פריזמה
              <br>
              הודעה זו נשלחה אוטומטית ממערכת ניהול האירועים.
            </td>
          </tr>
        </table>

      </td>
    </tr>
  </table>
