$V2$,
       subject = $V2$%name%, מחר נפתחת ההרשמה לאירוע המותגים$V2$,
       name = $V2$מחר נפתחת ההרשמה לאירוע המותגים (Email)$V2$
 WHERE tenant_id = '8d8cfa7e-ef58-49af-9702-a862d459cccb'
   AND slug      = 'event_will_open_tomorrow_email_he'
   AND channel   = 'email'
   AND language  = 'he';

-- event_will_open_tomorrow_sms_he (UPDATE existing V1 → V2)
UPDATE crm_message_templates
   SET body = $V2$עדכון ממערכת אירועי המותגים של אופטיקה פריזמה 📅

ההרשמה לאירוע הקרוב אליו נרשמתם תיפתח מחר.

לידיעתכם: על מנת לשמור על איכות השירות וחוויית הקנייה, מספר המשתתפים מוגבל ל-%event_max_attendees%.

עם פתיחת ההרשמה תישלח אליכם הודעה נוספת. פרטים מלאים נשלחו אליכם במייל 📧

צוות אופטיקה פריזמה 💛

להסרה: %unsubscribe_url%
$V2$,
       subject = NULL,
       name = $V2$מחר נפתחת ההרשמה לאירוע המותגים (SMS)$V2$
 WHERE tenant_id = '8d8cfa7e-ef58-49af-9702-a862d459cccb'
   AND slug      = 'event_will_open_tomorrow_sms_he'
   AND channel   = 'sms'
   AND language  = 'he';

-- event_registration_open_email_he (UPDATE existing V1 → V2)
UPDATE crm_message_templates
   SET body = $V2$<!--
  ═══════════════════════════════════════════════════════════════════
  SuperSale Event-Registration-Open Email — v2 (canon-compliant)
  ═══════════════════════════════════════════════════════════════════
  CRM slug: event_registration_open_email_he
  Template position: Stage 3 (THE critical CTA email — drives event registration)
  Trigger: Event registration opens; sent to all opted-in leads
  From: events@prizma-optic.co.il
  Subject: %name%, ההרשמה לאירוע %event_name% נפתחה

  Variables in use (CRM substitution syntax):
    %name%                   = lead's full name
    %event_name%             = event name
    %event_date%             = event date (DD/MM/YYYY)
    %event_day_of_week%      = day-of-week derived from event_date (e.g., "יום שישי")  *** REQUIRES NEW SYSTEM FIELD ***
    %event_time%             = event hours (e.g., "10:00 - 18:00")
    %event_max_attendees%    = numeric cap on attendance for this specific event
    %event_deposit_amount%   = deposit amount per event (e.g., "50") in NIS  *** REQUIRES NEW SYSTEM FIELD ***
    %registration_url%       = unique registration link for this lead
    %unsubscribe_url%        = per-recipient unsubscribe URL

  All tenant values (Prizma) hardcoded inline per Daniel's directive 2026-04-28.
  When tenant 2 onboards, SPEC #11 will plumb {{tenant.*}} variables. Until then: hardcoded.

  Canon: PRIZMA_DESIGN_SYSTEM_CANONICAL.md v1.1 (2026-04-28)
  Copy decisions: COPY_DECISIONS_LOG.md → "Template 4 — event_registration_open_email_he"
  ═══════════════════════════════════════════════════════════════════
-->
<!DOCTYPE html>
<html dir="rtl" lang="he">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ההרשמה נפתחה - אופטיקה פריזמה</title>

  <!-- Rubik web font -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;700&display=swap" rel="stylesheet">

  <style>
    body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
    table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
    img { -ms-interpolation-mode: bicubic; border: 0; height: auto; line-height: 100%; outline: none; text-decoration: none; }
    table { border-collapse: collapse !important; }
    body {
      margin: 0 !important;
      padding: 0 !important;
      width: 100% !important;
      background-color: #000000;
      font-family: 'Rubik', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    }
    @media screen and (max-width: 600px) {
      .container { width: 100% !important; }
      .mobile-padding { padding-left: 20px !important; padding-right: 20px !important; }
      .mobile-btn { width: 100% !important; display: block !important; box-sizing: border-box; }
      .event-box { padding: 20px !important; }
    }
  </style>
</head>
<body style="margin:0; padding:0; background-color:#000000; direction:rtl; font-family:'Rubik','Segoe UI',Tahoma,sans-serif;">
  <table border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color:#000000; background-image: radial-gradient(circle at 50% 0%, #1a1a1a 0%, #000000 70%);">
    <tr>
      <td align="center" style="padding: 40px 0;">

        <!-- Main Container -->
        <table border="0" cellpadding="0" cellspacing="0" width="600" class="container" style="max-width:600px; background-color:#1a1a1a; border-radius:12px; overflow:hidden; border: 1px solid #2d2d2d; box-shadow: 0 10px 40px rgba(201, 165, 85, 0.15);">

          <!-- Gold Bar Top — canonical 3-stop gradient -->
          <tr>
            <td height="4" style="background: linear-gradient(135deg, #c9a555 0%, #c9a555 50%, #e8da94 100%); line-height:4px; font-size:0;">&nbsp;</td>
          </tr>

          <!-- Wordmark -->
          <tr>
            <td align="center" style="padding: 40px 0 20px 0;">
              <p style="margin:0; color:#c9a555; font-size:24px; font-weight:700; letter-spacing:4px; text-transform:uppercase; font-family:'Rubik','Segoe UI',sans-serif;">
                PRIZMA OPTIC
              </p>
              <p style="margin:5px 0 0 0; color:#999999; font-size:12px; letter-spacing:2px; text-transform:uppercase; font-family:'Rubik','Segoe UI',sans-serif;">
                Luxury Eyewear Events
              </p>
            </td>
          </tr>

          <!-- Main Content -->
          <tr>
            <td class="mobile-padding" style="padding: 20px 50px 40px 50px; text-align:right;">

              <h1 style="margin:0 0 15px 0; font-size:28px; font-weight:700; color:#ffffff; text-align:center; line-height:1.3;">
                היי %name%, ההרשמה נפתחה
              </h1>

              <p style="margin:0 0 25px 0; font-size:16px; line-height:1.7; color:#cccccc; text-align:center;">
                ניתן להירשם כעת ל-<strong style="color:#ffffff;">%event_name%</strong>.
                <br>
                כדי שנוכל להעניק לכל המשתתפים שירות אישי ומקצועי,
                <br>
                הרכישה בהטבות האירוע תתאפשר ל-<strong style="color:#ffffff;">%event_max_attendees%</strong> מוזמנים בלבד שאושרו במערכת וקיבלו קופון אישי.
              </p>

              <!-- ═══ EVENT DETAILS CARD (gold right-border) ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color:#1a1a1a; border:1px solid #2d2d2d; border-right:4px solid #c9a555; border-radius:12px; margin-bottom:25px;">
                <tr>
                  <td class="event-box" style="padding: 25px;">
                    <p style="margin:0 0 5px 0; font-size:12px; font-weight:700; color:#c9a555; text-transform:uppercase; letter-spacing:0.15em;">
                      פרטי האירוע
                    </p>
                    <p style="margin:0 0 18px 0; font-size:22px; font-weight:700; color:#ffffff;">
                      %event_name%
                    </p>
                    <table border="0" cellpadding="0" cellspacing="0">
                      <tr>
                        <td width="32" valign="middle" style="padding-bottom:12px;">
                          <!-- Heroicons outline: calendar -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#c9a555" stroke-width="1.5" style="vertical-align:middle;">
                            <path stroke-linecap="round" stroke-linejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5"/>
                          </svg>
                        </td>
                        <td valign="middle" style="font-size:16px; color:#ffffff; padding-bottom:12px;">
                          <strong>%event_day_of_week%, %event_date%</strong>
                        </td>
                      </tr>
                      <tr>
                        <td width="32" valign="middle" style="padding-bottom:12px;">
                          <!-- Heroicons outline: clock -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#c9a555" stroke-width="1.5" style="vertical-align:middle;">
                            <path stroke-linecap="round" stroke-linejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z"/>
                          </svg>
                        </td>
                        <td valign="middle" style="font-size:16px; color:#cccccc; padding-bottom:12px;">
                          שעות הפעילות: %event_time%
                        </td>
                      </tr>
                      <tr>
                        <td width="32" valign="middle">
                          <!-- Heroicons solid: map-pin -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="#c9a555" style="vertical-align:middle;">
                            <path fill-rule="evenodd" d="M11.54 22.351l.07.04.028.016a.76.76 0 00.723 0l.028-.015.071-.041a16.975 16.975 0 001.144-.742 19.58 19.58 0 002.683-2.282c1.944-1.99 3.963-4.98 3.963-8.827a8.25 8.25 0 00-16.5 0c0 3.846 2.02 6.837 3.963 8.827a19.58 19.58 0 002.682 2.282 16.975 16.975 0 001.145.742zM12 13.5a3 3 0 100-6 3 3 0 000 6z" clip-rule="evenodd"/>
                          </svg>
                        </td>
                        <td valign="middle" style="font-size:16px; color:#cccccc;">
                          הרצל 32, אשקלון (יש חניה במקום)
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>
              </table>

              <!-- ═══ IMPORTANT INFO BLOCK ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-bottom: 30px; background-color:#1a1a1a; border-radius:12px; border:1px solid #2d2d2d;">
                <tr>
                  <td style="padding: 20px;">
                    <h3 style="margin:0 0 12px 0; font-size:16px; font-weight:700; color:#c9a555;">מידע חשוב בנושא הרישום</h3>

                    <p style="margin:0 0 12px 0; color:#dddddd; font-size:14px; line-height:1.6;">
                      <strong style="color:#ffffff;">מומלץ להירשם כמה שיותר מוקדם:</strong> המערכת קולטת %event_max_attendees% משתתפים לאירוע. במידה והמכסה תתמלא, שאר הנרשמים יועברו אוטומטית לרשימת המתנה.
                    </p>

                    <p style="margin:0 0 12px 0; color:#dddddd; font-size:14px; line-height:1.6;">
                      <strong style="color:#ffffff;">שריון מקום באירוע:</strong> ההשתתפות באירוע כרוכה בדמי שריון מקום בסך <strong style="color:#e8da94;">%event_deposit_amount% ₪</strong>, המקוזזים במלואם מהקנייה ביום האירוע (או מוחזרים בביטול עד 48 שעות לפני). <a href="https://prizma-optic.co.il/supersale-takanon/" style="color:#c9a555; text-decoration:underline;">פרטים בתקנון</a>.
