              <!-- ═══ PRIMARY CTA — canon §4.1 Style 1 ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%">
                <tr>
                  <td align="center">
                    <a href="%registration_url%" class="mobile-btn" style="display:inline-block; padding:18px 45px; background:linear-gradient(135deg, #c9a555 0%, #c9a555 50%, #e8da94 100%); color:#1a1a1a; font-family:'Rubik','Segoe UI',sans-serif; font-size:17px; font-weight:700; text-decoration:none; border-radius:9999px; letter-spacing:0.3px; box-shadow: 0 8px 16px rgba(0, 0, 0, 0.3);">
                      בדיקת זכאות ורישום לאירוע
                    </a>
