              </table>

              <p style="margin:15px 0 0 0; text-align:center; font-size:13px; color:#999999; line-height: 1.5;">
                *מימוש הטבות האירוע (כולל מחירי אירוע והתחייבות למחיר) מותנה באישור סופי וקבלת קופון אישי.
              </p>

              <!-- Divider -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin: 40px 0;">
                <tr>
                  <td style="border-top: 1px solid #2d2d2d;"></td>
                </tr>
              </table>

              <!-- ═══ SECONDARY LINKS ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%">
                <tr>
                  <td align="center">
                    <table border="0" cellpadding="0" cellspacing="0" role="presentation" style="margin: 0 auto;">
                      <tr>
