                    <p style="margin:0 0 5px 0; font-size:12px; font-weight:700; color:#c9a555; text-transform:uppercase; letter-spacing:0.15em;">
                      פרטי האירוע החדש
                    </p>
                    <p style="margin:0 0 18px 0; font-size:22px; font-weight:700; color:#ffffff;">
                      %event_name%
                    </p>
                    <table border="0" cellpadding="0" cellspacing="0">
                      <tr>
                        <td width="32" valign="middle" style="padding-bottom:12px;">
                          <!-- Heroicons outline: calendar -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#c9a555" stroke-width="1.5" style="vertical-align:middle;">
                            <path stroke-linecap="round" stroke-linejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5"/>
                          </svg>
                        </td>
                        <td valign="middle" style="font-size:16px; color:#ffffff; padding-bottom:12px;">
                          <strong>%event_day_of_week%, %event_date%</strong>
                        </td>
                      </tr>
                      <tr>
                        <td width="32" valign="middle">
                          <!-- Heroicons outline: clock -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#c9a555" stroke-width="1.5" style="vertical-align:middle;">
                            <path stroke-linecap="round" stroke-linejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z"/>
                          </svg>
                        </td>
                        <td valign="middle" style="font-size:16px; color:#cccccc;">
                          שעות הפעילות: %event_time%
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>
              </table>

              <!-- ═══ PAYMENT NOTICE (gold-tinted, canon §4.4 dark variant) ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color: rgba(201,165,85,0.06); border:1px solid rgba(201,165,85,0.40); border-radius:12px; margin-bottom:25px;">
                <tr>
                  <td style="padding: 18px 22px;">
                    <table border="0" cellpadding="0" cellspacing="0">
                      <tr>
                        <td valign="middle" style="padding-bottom:8px;">
                          <!-- Heroicons solid: lock-closed -->
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="#e8da94" style="vertical-align:middle; margin-left:6px;">
                            <path fill-rule="evenodd" d="M12 1.5a5.25 5.25 0 00-5.25 5.25v3a3 3 0 00-3 3v6.75a3 3 0 003 3h10.5a3 3 0 003-3v-6.75a3 3 0 00-3-3v-3c0-2.9-2.35-5.25-5.25-5.25zm3.75 8.25v-3a3.75 3.75 0 10-7.5 0v3h7.5z" clip-rule="evenodd"/>
                          </svg>
                          <span style="font-size:12px; font-weight:700; color:#e8da94; text-transform:uppercase; letter-spacing:0.15em;">להשלמת השריון</span>
                        </td>
                      </tr>
                    </table>
                    <p style="margin:0 0 12px 0; font-size:15px; line-height:1.7; color:#cccccc;">
                      להשלמת השריון וקבלת הקופון האישי, נא להסדיר דמי שריון מקום בסך <strong style="color:#e8da94;">%event_deposit_amount% ₪</strong>.
                    </p>
                    <p style="margin:0; font-size:13px; line-height:1.6; color:#999999;">
                      דמי השריון מקוזזים במלואם מהקנייה ביום האירוע, או מוחזרים בביטול עד 48 שעות לפני. <a href="https://prizma-optic.co.il/supersale-takanon/" style="color:#c9a555; text-decoration:underline;">פרטים בתקנון</a>.
                    </p>
                  </td>
                </tr>
              </table>

              <!-- ═══ PRIMARY CTA ═══ -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-bottom:25px;">
                <tr>
                  <td align="center">
                    <a href="%payment_url_50%" class="mobile-btn" style="display:inline-block; padding:18px 45px; background:linear-gradient(135deg, #c9a555 0%, #c9a555 50%, #e8da94 100%); color:#1a1a1a; font-family:'Rubik','Segoe UI',sans-serif; font-size:17px; font-weight:700; text-decoration:none; border-radius:9999px; letter-spacing:0.3px; box-shadow: 0 8px 16px rgba(0, 0, 0, 0.3);">
                      תשלום דמי השריון
                    </a>
                  </td>
                </tr>
              </table>

              <!-- Sign Off -->
              <table border="0" cellpadding="0" cellspacing="0" width="100%" style="margin-top: 15px; border-top: 1px solid #2d2d2d;">
                <tr>
                  <td style="padding-top: 20px;">
                    <p style="margin:0; font-size:15px; color:#ffffff;">נתראה,</p>
                    <p style="margin:5px 0 0 0; font-size:15px; color:#c9a555; font-weight:700;">צוות אופטיקה פריזמה</p>
                  </td>
                </tr>
              </table>

            </td>
          </tr>

          <!-- Unsubscribe Block -->
          <tr>
            <td align="center" style="padding: 18px 20px; border-top: 1px solid #2d2d2d; color:#999999; font-size:12px; line-height:1.6;">
              <p style="margin:0 0 10px 0;">המייל נשלח אליכם בעקבות העברת מקומכם בין אירועי המותגים של אופטיקה פריזמה.</p>
              <a href="%unsubscribe_url%" style="color:#c9a555; text-decoration:underline;">הסרה מרשימת התפוצה</a>
            </td>
          </tr>

        </table>

        <!-- ═══ COPYRIGHT ═══ -->
        <table border="0" cellpadding="0" cellspacing="0" width="600" class="container">
          <tr>
            <td align="center" style="padding: 20px 0; color:#666666; font-size:11px; line-height:1.6;">
              © כל הזכויות שמורות לאופטיקה פריזמה | הרצל 32, אשקלון
              <br>
              ההטבות והמחירים בכפוף לתנאי התקנון וזמינות המלאי.
            </td>
          </tr>
        </table>

      </td>
    </tr>
  </table>
</body>
</html>
$V2$,
  true,
  now()
)
ON CONFLICT (tenant_id, slug) DO UPDATE
  SET body = EXCLUDED.body,
      subject = EXCLUDED.subject,
      name = EXCLUDED.name,
      is_active = EXCLUDED.is_active;

